===== CheckIdempotencyKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.web.HttpHeaderParameter;
import org.springframework.samples.petclinic.rest.escalation.IdempotentReplayException;

/**
 * First step of {@code POST /api/owners}: if the request carries an {@code Idempotency-Key} that has
 * already created an owner, short-circuits the pipeline with an {@link IdempotentReplayException}
 * (handled as a 200 returning the original owner) rather than creating a duplicate. A request with no
 * key, or an unseen key, falls through to the normal create pipeline. Reads only the header — not the
 * body — so the body remains free for {@link NormalizeOwnerAddress} to bind once.
 */
public class CheckIdempotencyKey {

    public void service(@HttpHeaderParameter("Idempotency-Key") String idempotencyKey,
            IdempotencyStore store) throws IdempotentReplayException {
        Integer existingOwnerId = store.find(idempotencyKey);
        if (existingOwnerId != null) {
            throw new IdempotentReplayException(existingOwnerId);
        }
    }
}
===== NormalizeOwnerAddress =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}: reads the request body once and normalizes whichever
 * address form was supplied, then republishes the body for the rest of the pipeline.
 *
 * <p>The structured form (a non-blank {@code addressLine1}, with an optional {@code addressLine2})
 * is preferred when present; otherwise the flat {@code address} input is used (backward compatible).
 * Every supplied line is normalized in place (trim and collapse whitespace, upper-case, expand
 * common abbreviations — see {@link OwnerAddressNormalizer}). The flat {@code address} is set to the
 * composed, normalized value: the normalized {@code addressLine1}, with a single space and the
 * normalized {@code addressLine2} appended when {@code addressLine2} is present. Running before
 * {@link RequireOwnerFields} means the required-field check sees the composed address, so a request
 * that supplies no address in either form is rejected; it also means the stored and returned
 * address, and every later step that reads the address, use the normalized form.
 */
public class NormalizeOwnerAddress {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated) {
        String line1 = request.getAddressLine1();
        if (line1 != null && !line1.isBlank()) {
            // Structured form takes precedence over the flat 'address'.
            String normalizedLine1 = OwnerAddressNormalizer.normalize(line1);
            String normalizedLine2 = OwnerAddressNormalizer.normalize(request.getAddressLine2());
            request.setAddressLine1(normalizedLine1);
            request.setAddressLine2(normalizedLine2.isEmpty() ? null : normalizedLine2);
            String composed = normalizedLine2.isEmpty() ? normalizedLine1
                    : normalizedLine1 + " " + normalizedLine2;
            request.setAddress(composed);
        }
        else {
            request.setAddress(OwnerAddressNormalizer.normalize(request.getAddress()));
        }
        validated.set(request);
    }
}
===== RequireOwnerFields =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Runs after {@link NormalizeOwnerAddress} on {@code POST /api/owners}, reading the published body:
 * rejects a request that is missing or blank in any of firstName, lastName, address, city or
 * telephone, listing every offending field. Because the address has already been normalized, an
 * address that is blank after normalization is reported here as a missing field.
 */
public class RequireOwnerFields {

    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        require(missing, "firstName", request.getFirstName());
        require(missing, "lastName", request.getLastName());
        require(missing, "address", request.getAddress());
        require(missing, "city", request.getCity());
        require(missing, "telephone", request.getTelephone());
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
    }

    private static void require(List<String> missing, String field, String value) {
        if (value == null || value.isBlank()) {
            missing.add(field);
        }
    }
}
===== ValidateOwnerPostcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
import org.springframework.samples.petclinic.rest.function.common.Localities;

/**
 * Validates the owner's postcode WHEN PRESENT, reading the published request body. An absent or
 * blank postcode is accepted (the field is optional). When supplied it must be exactly four digits;
 * if the city has a known region ({@link Localities}), the code must also fall inside that region's
 * inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
 * accepts any 4-digit postcode. Anything else is rejected with 400 via
 * {@link InvalidPostcodeException}.
 */
public class ValidateOwnerPostcode {

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException(postcode);
        }
        int[] range = REGION_POSTCODES.get(Localities.of(request.getCity()));
        if (range == null) {
            return; // city with no known region accepts any 4-digit postcode
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(postcode);
        }
    }
}
