package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Validates the owner's registrationDate WHEN PRESENT, reading the published request body. An
 * absent date is accepted (it defaults to the server date later, see
 * {@link DefaultOwnerRegistrationDate}). A supplied date must not be later than the server's current
 * date; a future date is rejected with 400 via {@link FutureRegistrationDateException}.
 */
public class ValidateOwnerRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied != null && supplied.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(supplied);
        }
    }
}
===== NormalizeOwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Runs after {@link RequireOwnerFields} on {@code POST /api/owners}: normalizes the telephone into
 * E.164 form, replacing the field in place (so {@link BuildOwner} maps the normalized value).
 * <p>
 * Spaces, dashes and brackets are stripped. When the number carries a leading {@code '+'} the
 * country code is kept as given; otherwise country code {@code '+61'} is assumed and a single
 * leading {@code '0'} is dropped from the national digits. The result must have 8 to 15 digits
 * after the {@code '+'}.
 * <p>
 * The national-number length is then validated against the country code: {@code '+61'} requires
 * exactly 9 national digits and {@code '+1'} requires exactly 10. A number that cannot form a valid
 * E.164 string, or whose national number is the wrong length for its country code, is rejected with
 * 400 via {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    /**
     * Country code (digits after the {@code '+'}) to the exact national-number length it requires.
     * Longest prefixes first so {@code '61'} is matched before {@code '1'}.
     */
    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();

    static {
        NATIONAL_LENGTHS.put("61", 9);
        NATIONAL_LENGTHS.put("1", 10);
    }

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String raw = request.getTelephone();
        String stripped = raw == null ? "" : raw.replaceAll("[\\s\\-()]", "");

        String digits;
        if (stripped.startsWith("+")) {
            digits = stripped.substring(1);
        }
        else {
            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
            digits = "61" + national;
        }

        if (!digits.matches("\\d{8,15}")) {
            throw new InvalidTelephoneException(raw);
        }

        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
            String code = country.getKey();
            if (digits.startsWith(code)) {
                if (digits.length() - code.length() != country.getValue()) {
                    throw new InvalidTelephoneException(raw);
                }
                break;
            }
        }

        request.setTelephone("+" + digits);
    }
}
===== NormalizeOwnerEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Email is optional. When absent (null or blank) this step leaves the request untouched. When
 * present it must be a syntactically valid address; the value is lower-cased in place (so the
 * mapper stores and later steps return the normalized form) and an invalid address is rejected
 * with 400 via {@link InvalidEmailException}.
 */
public class NormalizeOwnerEmail {

    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String raw = request.getEmail();
        if (raw == null || raw.isBlank()) {
            return;
        }
        String email = raw.toLowerCase(Locale.ROOT);
        if (!EMAIL.matcher(email).matches()) {
            throw new InvalidEmailException(raw);
        }
        request.setEmail(email);
    }
}
===== RejectDisposableEmailDomain =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;

/**
 * Rejects an email whose domain is on the disposable-domain blocklist. Email is optional, so an
 * absent or blank email is accepted. Runs after {@link NormalizeOwnerEmail}, which has already
 * lower-cased and syntactically validated the address, so the domain is the substring after the
 * final {@code @}. A blocklisted domain is rejected with 400 via
 * {@link DisposableEmailDomainException}.
 */
public class RejectDisposableEmailDomain {

    private static final Set<String> BLOCKED_DOMAINS = Set.of(
            "mailinator.com",
            "tempmail.com",
            "guerrillamail.com");

    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return; // optional when absent
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return; // not a syntactically valid address; NormalizeOwnerEmail already guards this
        }
        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
        if (BLOCKED_DOMAINS.contains(domain)) {
            throw new DisposableEmailDomainException(email);
        }
    }
}
===== CheckUniqueOwnerIdentity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * The single duplicate check on {@code POST /api/owners}, keyed off the deterministic
 * {@link OwnerHousehold} householdId. Rejects with 409 via {@link DuplicateIdentityException} when
 * either:
 * <ul>
 * <li>the new owner's whole {@link OwnerIdentityKey} ({@code <telephone>|<email>|<householdId>})
 * equals an existing owner's — an exact duplicate; or</li>
 * <li>an existing owner shares the new owner's household (same {@code (lastName, postcode)}, hence
 * the same computed householdId) — a household duplicate. This is bypassed when the request opts in
 * with {@code sharesHousehold} true, in which case the owner is created as a declared household
 * member.</li>
 * </ul>
 * Runs before {@link BuildOwner} so no owner is created on conflict, and resolves the householdId
 * the request would receive so its key matches the one assigned and returned afterwards.
 */
public class CheckUniqueOwnerIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String householdId = OwnerHousehold.householdId(request);
        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(), householdId);
        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
        for (Owner existing : ownerRepository.findAll()) {
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner does not block a new registration
            }
            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
            if (!sharesHousehold && householdId.equals(OwnerHousehold.householdId(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
===== CheckOwnerCityCapacity =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on conflict):
 * rejects the request with 409 via {@link CityAtCapacityException} when the request's city already
 * contains {@link #MAX_OWNERS_PER_CITY} or more owners, compared case-insensitively with collapsed
 * whitespace.
 */
public class CheckOwnerCityCapacity {

    /** Maximum owners allowed per city; the next create in a full city is rejected. */
    static final int MAX_OWNERS_PER_CITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = normalize(request.getCity());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equals(normalize(existing.getCity())) && ++count >= MAX_OWNERS_PER_CITY) {
                throw new CityAtCapacityException(request.getCity());
            }
        }
    }

    /** Lower-case and collapse runs of whitespace so comparison is case- and whitespace-insensitive. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
