31	/**
32	 * First step of {@code POST /api/owners}: reads the request body once and normalizes whichever
33	 * address form was supplied, then republishes the body for the rest of the pipeline.
34	 *
35	 * <p>The structured form (a non-blank {@code addressLine1}, with an optional {@code addressLine2})
36	 * is preferred when present; otherwise the flat {@code address} input is used (backward compatible).
37	 * Every supplied line is normalized in place (trim and collapse whitespace, upper-case, expand
38	 * common abbreviations — see {@link OwnerAddressNormalizer}). The flat {@code address} is set to the
39	 * composed, normalized value: the normalized {@code addressLine1}, with a single space and the
40	 * normalized {@code addressLine2} appended when {@code addressLine2} is present. Running before
41	 * {@link RequireOwnerFields} means the required-field check sees the composed address, so a request
42	 * that supplies no address in either form is rejected; it also means the stored and returned
43	 * address, and every later step that reads the address, use the normalized form.
44	 */
45	public class NormalizeOwnerAddress {
46	
47	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated) {
48	        String line1 = request.getAddressLine1();
49	        if (line1 != null && !line1.isBlank()) {
50	            // Structured form takes precedence over the flat 'address'.
51	            String normalizedLine1 = OwnerAddressNormalizer.normalize(line1);
52	            String normalizedLine2 = OwnerAddressNormalizer.normalize(request.getAddressLine2());
53	            request.setAddressLine1(normalizedLine1);
54	            request.setAddressLine2(normalizedLine2.isEmpty() ? null : normalizedLine2);
55	            String composed = normalizedLine2.isEmpty() ? normalizedLine1
56	                    : normalizedLine1 + " " + normalizedLine2;
57	            request.setAddress(composed);
58	        }
59	        else {
60	            request.setAddress(OwnerAddressNormalizer.normalize(request.getAddress()));
61	        }
62	        validated.set(request);
63	    }
64	}
