111	/**
112	 * Validates the owner's postcode WHEN PRESENT, reading the published request body. An absent or
113	 * blank postcode is accepted (the field is optional). When supplied it must be exactly four digits;
114	 * if the city has a known region ({@link Localities}), the code must also fall inside that region's
115	 * inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
116	 * accepts any 4-digit postcode. Anything else is rejected with 400 via
117	 * {@link InvalidPostcodeException}.
118	 */
119	public class ValidateOwnerPostcode {
120	
121	    /** Region -> inclusive 4-digit postcode range {low, high}. */
122	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
123	            "NSW", new int[] {2000, 2099},
124	            "VIC", new int[] {3000, 3099},
125	            "QLD", new int[] {4000, 4099});
126	
127	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
128	        String postcode = request.getPostcode();
129	        if (postcode == null || postcode.isBlank()) {
130	            return; // optional when absent
131	        }
132	        if (!postcode.matches("[0-9]{4}")) {
133	            throw new InvalidPostcodeException(postcode);
134	        }
135	        int[] range = REGION_POSTCODES.get(Localities.of(request.getCity()));
136	        if (range == null) {
137	            return; // city with no known region accepts any 4-digit postcode
138	        }
139	        int value = Integer.parseInt(postcode);
140	        if (value < range[0] || value > range[1]) {
141	            throw new InvalidPostcodeException(postcode);
142	        }
143	    }
144	}
