170	package org.springframework.samples.petclinic.rest.function.owner;
171	
172	import java.util.LinkedHashMap;
173	import java.util.Map;
174	
175	import net.officefloor.plugin.variable.Val;
176	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
177	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
178	
179	/**
180	 * Runs after {@link RequireOwnerFields} on {@code POST /api/owners}: normalizes the telephone into
181	 * E.164 form, replacing the field in place (so {@link BuildOwner} maps the normalized value).
182	 * <p>
183	 * Spaces, dashes and brackets are stripped. When the number carries a leading {@code '+'} the
184	 * country code is kept as given; otherwise country code {@code '+61'} is assumed and a single
185	 * leading {@code '0'} is dropped from the national digits. The result must have 8 to 15 digits
186	 * after the {@code '+'}.
187	 * <p>
188	 * The national-number length is then validated against the country code: {@code '+61'} requires
189	 * exactly 9 national digits and {@code '+1'} requires exactly 10. A number that cannot form a valid
190	 * E.164 string, or whose national number is the wrong length for its country code, is rejected with
191	 * 400 via {@link InvalidTelephoneException}.
192	 */
193	public class NormalizeOwnerTelephone {
194	
195	    /**
196	     * Country code (digits after the {@code '+'}) to the exact national-number length it requires.
197	     * Longest prefixes first so {@code '61'} is matched before {@code '1'}.
198	     */
199	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
200	
201	    static {
202	        NATIONAL_LENGTHS.put("61", 9);
203	        NATIONAL_LENGTHS.put("1", 10);
204	    }
205	
206	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
207	        String raw = request.getTelephone();
208	        String stripped = raw == null ? "" : raw.replaceAll("[\\s\\-()]", "");
209	
210	        String digits;
211	        if (stripped.startsWith("+")) {
212	            digits = stripped.substring(1);
213	        }
214	        else {
215	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
216	            digits = "61" + national;
217	        }
218	
219	        if (!digits.matches("\\d{8,15}")) {
220	            throw new InvalidTelephoneException(raw);
221	        }
222	
223	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
224	            String code = country.getKey();
225	            if (digits.startsWith(code)) {
226	                if (digits.length() - code.length() != country.getValue()) {
227	                    throw new InvalidTelephoneException(raw);
228	                }
229	                break;
230	            }
231	        }
232	
233	        request.setTelephone("+" + digits);
234	    }
235	}
