336	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(), householdId);
337	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
338	        for (Owner existing : ownerRepository.findAll()) {
339	            if (Boolean.TRUE.equals(existing.getDeleted())) {
340	                continue; // a soft-deleted owner does not block a new registration
341	            }
342	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
343	                throw new DuplicateIdentityException(identityKey);
344	            }
345	            if (!sharesHousehold && householdId.equals(OwnerHousehold.householdId(existing))) {
346	                throw new DuplicateIdentityException(identityKey);
347	            }
348	        }
349	    }
