485	package org.springframework.samples.petclinic.rest.function.owner;
486	
487	import java.nio.charset.StandardCharsets;
488	import java.security.MessageDigest;
489	import java.security.NoSuchAlgorithmException;
490	
491	import java.util.HashSet;
492	import java.util.Set;
493	
494	import net.officefloor.plugin.variable.Val;
495	import org.springframework.samples.petclinic.model.Owner;
496	import org.springframework.samples.petclinic.rest.function.common.Localities;
497	import org.springframework.samples.petclinic.repository.OwnerRepository;
498	
499	/**
500	 * Assigns a new owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
501	 * region derived from the postcode alone ({@link Localities#ofPostcode}: NSW 2000-2099, VIC
502	 * 3000-3099, QLD 4000-4099, else {@code UNKNOWN}) and HASH8 is the first 8 UPPER-case hex characters
503	 * of the SHA-256 digest over {@code normalizedTelephone + lastName} (e.g. {@code NSW-3F9A0C71}).
504	 * There are no per-city sequence numbers: the identity is stable for a given telephone, surname and
505	 * region. When the computed {@code <REGION>-<HASH8>} collides with an existing owner's
506	 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more that makes
507	 * it unique, so distinct owners always receive distinct codes.
508	 * Runs after {@link BuildOwner} maps the request (so the telephone is already the normalized
509	 * E.164 value) and before {@link SaveOwner} persists it; every downstream region-and-hash value (the
510	 * membership number and its check digit, the locality and the create audit record) flows from this
511	 * code.
512	 */
513	public class AssignOwnerCustomerCode {
514	
515	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
516	        String region = Localities.ofPostcode(owner.getPostcode());
517	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
518	        String base = region + "-" + hash8;
519	
520	        Set<String> taken = new HashSet<>();
521	        for (Owner existing : ownerRepository.findAll()) {
522	            if (existing.getCustomerCode() != null) {
523	                taken.add(existing.getCustomerCode());
524	            }
525	        }
526	
527	        String customerCode = base;
528	        for (int n = 2; taken.contains(customerCode); n++) {
529	            customerCode = base + "-" + n;
530	        }
531	        owner.setCustomerCode(customerCode);
532	    }
533	
534	    /** First 8 UPPER-case hex characters of SHA-256 over the UTF-8 bytes of {@code input}. */
535	    private static String hash8(String input) {
536	        try {
537	            byte[] digest = MessageDigest.getInstance("SHA-256")
538	                    .digest(input.getBytes(StandardCharsets.UTF_8));
539	            StringBuilder hex = new StringBuilder(8);
540	            for (byte b : digest) {
541	                hex.append(String.format("%02X", b));
542	                if (hex.length() >= 8) {
543	                    break;
544	                }
545	            }
546	            return hex.substring(0, 8);
547	        }
548	        catch (NoSuchAlgorithmException ex) {
549	            throw new IllegalStateException("SHA-256 not available", ex);
550	        }
551	    }
552	}
