619	 * {@link SaveOwner}, so it compares against the owners already stored, not the one being created.
620	 * When an existing owner shares this owner's last name (case-insensitive) and postcode but has a
621	 * different telephone, {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to that
622	 * owner's id; otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} null. An
623	 * owner that declared it shares a household ({@code sharesHousehold} true) is never flagged — a
624	 * declared household member is not a suspected duplicate. Both values are persisted so they are
625	 * returned unchanged on later reads of the owner.
626	 */
627	public class AssignOwnerPossibleDuplicate {
628	
629	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
630	        String lastName = owner.getLastName();
631	        String postcode = owner.getPostcode();
632	        String telephone = owner.getTelephone();
633	        owner.setPossibleDuplicate(false);
634	        owner.setPossibleDuplicateOf(null);
635	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
636	            return; // a declared household member is not a suspected duplicate
637	        }
638	        if (postcode == null) {
639	            return; // no postcode to share, so never a soft-match
640	        }
641	        for (Owner existing : ownerRepository.findAll()) {
642	            if (Boolean.TRUE.equals(existing.getDeleted())) {
643	                continue; // a soft-deleted owner is not a duplicate match
644	            }
645	            if (equalsIgnoreCase(lastName, existing.getLastName())
646	                    && postcode.equals(existing.getPostcode())
647	                    && !equals(telephone, existing.getTelephone())) {
648	                owner.setPossibleDuplicate(true);
649	                owner.setPossibleDuplicateOf(existing.getId());
650	                return;
651	            }
652	        }
653	    }
654	
655	    private static boolean equalsIgnoreCase(String a, String b) {
656	        return a == null ? b == null : a.equalsIgnoreCase(b);
657	    }
658	
659	    private static boolean equals(String a, String b) {
660	        return a == null ? b == null : a.equals(b);
661	    }
