===== AssignOwnerHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Runs on {@code POST /api/owners} after {@link BuildOwner}, and assigns the new owner its
 * deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
 * {@code <normalizedLastName>|<postcode>} (see {@link OwnerHousehold}). Every owner gets one, so
 * owners with the same last name and postcode share it automatically — no {@code sharesHousehold}
 * opt-in and no lookup of existing members is needed. The same computation is used by
 * {@link CheckUniqueOwnerIdentity}, so the householdId used in the identity key and the household
 * duplicate check matches the one stored and returned.
 */
public class AssignOwnerHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner) {
        owner.setHouseholdId(OwnerHousehold.householdId(request));
    }
}
===== DefaultOwnerRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Establishes a new owner's effective registration date: the date supplied in the request, or the
 * server's current date when the request omits it. The effective date must fall on a business day,
 * so a Saturday or Sunday — whether supplied or defaulted — rolls forward to the next Monday (see
 * {@link BusinessDay}). Runs after {@link BuildOwner} maps the request and before
 * {@link AssignOwnerMembershipNumber} (which derives its year segment from this value) and
 * {@link SaveOwner} persists it.
 */
public class DefaultOwnerRegistrationDate {

    public void service(@Val Owner owner) {
        LocalDate effective = owner.getRegistrationDate() == null ? LocalDate.now()
                : owner.getRegistrationDate();
        owner.setRegistrationDate(BusinessDay.rollForward(effective));
    }
}
===== AssignOwnerCustomerCode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.function.common.Localities;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a new owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
 * region derived from the postcode alone ({@link Localities#ofPostcode}: NSW 2000-2099, VIC
 * 3000-3099, QLD 4000-4099, else {@code UNKNOWN}) and HASH8 is the first 8 UPPER-case hex characters
 * of the SHA-256 digest over {@code normalizedTelephone + lastName} (e.g. {@code NSW-3F9A0C71}).
 * There are no per-city sequence numbers: the identity is stable for a given telephone, surname and
 * region. When the computed {@code <REGION>-<HASH8>} collides with an existing owner's
 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more that makes
 * it unique, so distinct owners always receive distinct codes.
 * Runs after {@link BuildOwner} maps the request (so the telephone is already the normalized
 * E.164 value) and before {@link SaveOwner} persists it; every downstream region-and-hash value (the
 * membership number and its check digit, the locality and the create audit record) flows from this
 * code.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = Localities.ofPostcode(owner.getPostcode());
        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
        String base = region + "-" + hash8;

        Set<String> taken = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getCustomerCode() != null) {
                taken.add(existing.getCustomerCode());
            }
        }

        String customerCode = base;
        for (int n = 2; taken.contains(customerCode); n++) {
            customerCode = base + "-" + n;
        }
        owner.setCustomerCode(customerCode);
    }

    /** First 8 UPPER-case hex characters of SHA-256 over the UTF-8 bytes of {@code input}. */
    private static String hash8(String input) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(8);
            for (byte b : digest) {
                hex.append(String.format("%02X", b));
                if (hex.length() >= 8) {
                    break;
                }
            }
            return hex.substring(0, 8);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}
===== AssignOwnerMembershipNumber =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns a new owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>} where YY is
 * the last two digits of the fiscal year (starting 1 July) of the business-day-adjusted registration
 * date (e.g. {@code NSW-3F9A0C71-M26}). Runs after
 * {@link AssignOwnerCustomerCode} sets the region-and-hash customer code and
 * {@link DefaultOwnerRegistrationDate}
 * ensures a registration date, and before {@link SaveOwner} persists it, so the value is stored and
 * returned unchanged on later reads of the owner.
 */
public class AssignOwnerMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}
===== AssignOwnerNamesakeCount =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a new owner's {@code namesakeCount}: the number of owners already stored that share this
 * owner's first and last name, compared case-insensitively, not counting the owner itself. Runs
 * after {@link BuildOwner} maps the request and before {@link SaveOwner} persists it, so the count
 * reflects the owners already stored, not the one being created. The value is persisted so it is
 * returned unchanged on later reads of the owner.
 */
public class AssignOwnerNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(firstName, existing.getFirstName())
                    && equalsIgnoreCase(lastName, existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}
===== AssignOwnerPossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a new owner as a possible (soft) duplicate. A hard duplicate is already rejected earlier by
 * {@link CheckUniqueOwnerIdentity}; this step runs after {@link BuildOwner} and before
 * {@link SaveOwner}, so it compares against the owners already stored, not the one being created.
 * When an existing owner shares this owner's last name (case-insensitive) and postcode but has a
 * different telephone, {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to that
 * owner's id; otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} null. An
 * owner that declared it shares a household ({@code sharesHousehold} true) is never flagged — a
 * declared household member is not a suspected duplicate. Both values are persisted so they are
 * returned unchanged on later reads of the owner.
 */
public class AssignOwnerPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        String telephone = owner.getTelephone();
        owner.setPossibleDuplicate(false);
        owner.setPossibleDuplicateOf(null);
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is not a suspected duplicate
        }
        if (postcode == null) {
            return; // no postcode to share, so never a soft-match
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner is not a duplicate match
            }
            if (equalsIgnoreCase(lastName, existing.getLastName())
                    && postcode.equals(existing.getPostcode())
                    && !equals(telephone, existing.getTelephone())) {
                owner.setPossibleDuplicate(true);
                owner.setPossibleDuplicateOf(existing.getId());
                return;
            }
        }
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }

    private static boolean equals(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }
}
